def check_7b7617bd_recent_files(actual_config_path, rule):
    """
    Evaluator for task 7b7617bd-L1_1: Set the maximum number of recent files to display in the menu to 15

    This function checks:
    1. The GIMP config file (gimprc) exists
    2. The max-recent-files setting is present and set to 15
    3. The config format follows GIMP's Lisp-like syntax: (max-recent-files 15)

    Args:
        actual_config_path: Path to the GIMP configuration file (gimprc) - from VM
        rule: Dictionary containing expected key-value pair
              Expected format: {"key": "max-recent-files", "value": "15"}

    Returns:
        float: 1.0 if success, 0.0 if failure
    """
    import os
    import logging
    import re

    logger = logging.getLogger(__name__)

    # Check if config path is provided
    if actual_config_path is None:
        logger.warning("Config path is None")
        return 0.0

    if not os.path.exists(actual_config_path):
        logger.error(f"Config file not found: {actual_config_path}")
        return 0.0

    try:
        # Read the config file
        with open(actual_config_path, 'r') as f:
            content = f.readlines()

        # Expected key and value from rule
        expected_key = rule.get("key", "max-recent-files")
        expected_value = rule.get("value", "15")

        logger.info(f"Checking for {expected_key} = {expected_value} in {actual_config_path}")

        # Search for the max-recent-files setting
        # GIMP config uses Lisp-like syntax: (max-recent-files 15)
        found_setting = False

        for line in content:
            # Skip comments and empty lines
            if line.strip().startswith('#') or line.strip() == '':
                continue

            # Check for the setting using regex
            # Match patterns like: (max-recent-files 15) or (max-recent-files 15\n)
            pattern = rf'\(\s*{re.escape(expected_key)}\s+(\d+)\s*\)'
            match = re.search(pattern, line)

            if match:
                actual_value = match.group(1)
                logger.info(f"Found {expected_key} = {actual_value}")

                if actual_value == expected_value:
                    found_setting = True
                    break

        result = 1.0 if found_setting else 0.0
        logger.info(f"check_7b7617bd_recent_files result: {result} (expected: {expected_value})")

        return result

    except Exception as e:
        logger.error(f"check_7b7617bd_recent_files error: {e}")
        return 0.0
